function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`show ${error?'error':''}`;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.className='',4200)}
async function api(url,options={}){const headers={...(options.headers||{})};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';if(['POST','PUT','PATCH','DELETE'].includes((options.method||'GET').toUpperCase()))headers['X-CSRF-Token']=document.querySelector('meta[name="csrf-token"]')?.content||'';const response=await fetch(url,{...options,headers});if(response.status===401){window.location.assign(`/login?next=${encodeURIComponent(window.location.pathname+window.location.search)}`);throw new Error('Sign in required')}if(!response.ok){let body={};try{body=await response.json()}catch{}const detail=body.detail;throw new Error(typeof detail==='object'?(detail.message||JSON.stringify(detail)):(detail||`Request failed (${response.status})`))}if(response.status===204)return null;return response.json()}
async function logout(){try{await api('/logout',{method:'POST'});window.location.assign('/login')}catch(error){toast(error.message,true)}}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function money(value){return value==null?'—':new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(value))}
function profileHref(row){return `/player/${encodeURIComponent(row.player_id)}?league_id=${encodeURIComponent(activeLeagueId())}`}
function playerFlags(row){const flags=[];if(row.rookie)flags.push('<span class="player-flag rookie">Rookie</span>');if(row.injury_status)flags.push(`<span class="player-flag injury">${escapeHtml(row.injury_status)}</span>`);if(row.source_confidence==='low')flags.push('<span class="player-flag limited">Limited sources</span>');return flags.join(' ')}
function switchLeague(value){const url=new URL(location.href);url.searchParams.set('league_id',value);location.href=url}
function shortDate(value){if(!value)return'Never';return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
async function syncMfl(){const button=document.querySelector('#sync-button');if(button){button.disabled=true;button.textContent='Synchronizing…'}try{const result=await api('/api/sync',{method:'POST'});toast(`Synchronized ${result.leagues.length} league(s)`);location.reload()}catch(error){toast(error.message,true);if(button){button.disabled=false;button.textContent='Synchronize MFL'}}}

document.addEventListener('keydown',event=>{if(event.key==='?'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){event.preventDefault();document.querySelector('#shortcut-help')?.showModal()}if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){const search=document.querySelector('input[type=search]');if(search){event.preventDefault();search.focus()}}if(event.key==='Escape'){document.querySelectorAll('dialog[open]').forEach(item=>item.close());const chat=document.querySelector('#assistant-window');if(chat&&!chat.hidden)closeAssistant()}})

function setSelectOptions(selector,items,allLabel='All positions'){const select=document.querySelector(selector);if(!select)return;const selected=select.value;select.innerHTML=`<option value="">${escapeHtml(allLabel)}</option>`+items.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('');select.value=items.includes(selected)?selected:''}
function initResizableTables(){document.querySelectorAll('.table-wrap table').forEach((table,tableIndex)=>{if(table.dataset.resizableReady||!table.tHead?.rows.length)return;const headers=[...table.tHead.rows[0].cells];if(headers.length<2)return;table.dataset.resizableReady='true';table.classList.add('resizable-table');const storageKey=table.dataset.columnKey||`draftdesk:columns:${location.pathname}:${tableIndex}`;let saved=[];try{saved=JSON.parse(localStorage.getItem(storageKey)||'[]')}catch{}const widths=headers.map((header,index)=>Math.max(60,Number(saved[index])||Math.ceil(header.getBoundingClientRect().width)));const group=document.createElement('colgroup');const columns=widths.map(width=>{const column=document.createElement('col');column.style.width=`${width}px`;group.appendChild(column);return column});table.insertBefore(group,table.firstChild);const apply=()=>{columns.forEach((column,index)=>column.style.width=`${widths[index]}px`);localStorage.setItem(storageKey,JSON.stringify(widths))};headers.slice(0,-1).forEach((header,index)=>{const handle=document.createElement('span');handle.className='column-resizer';handle.title='Drag to resize column';handle.addEventListener('pointerdown',event=>{event.preventDefault();handle.setPointerCapture(event.pointerId);const startX=event.clientX,current=widths[index],next=widths[index+1];const move=moveEvent=>{const delta=Math.max(60-current,Math.min(next-60,moveEvent.clientX-startX));widths[index]=current+delta;widths[index+1]=next-delta;apply()};const stop=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',stop);handle.removeEventListener('pointercancel',stop)};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop)});header.appendChild(handle)});apply()})}
document.addEventListener('DOMContentLoaded',initResizableTables)

let rankings=[];let auctionState=null;let auctionSort='overall_rank';let auctionDirection='asc';let saleMatchTimer=null;
async function refreshAuction(){const selectedId=document.querySelector('#sale-player-id')?.value||'';[auctionState,rankings]=await Promise.all([api(`/api/auction/state?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`),api(`/api/leagues/${encodeURIComponent(AUCTION_LEAGUE_ID)}/rankings`)]);const order=['QB','RB','WR','TE','PK','DEF'];const positions=[...new Set(rankings.map(row=>row.position))].sort((a,b)=>order.indexOf(a)-order.indexOf(b));setSelectOptions('#position-filter',positions);setSelectOptions('#auction-position-filter',positions,'All');renderPlayerMatcher();renderBudgets();renderRankings();renderFranchises();renderPurchases();const selected=rankings.find(row=>row.player_id===selectedId);if(selected)choosePlayer(selected.player_id,selected.player_name,selected.dynamic_bid??selected.suggested_auction_value,false);else clearAuctionPlayerSelection()}
function renderBudgets(){document.querySelector('#budget-grid').innerHTML=auctionState.franchises.map(team=>`<article class="budget"><h3>${escapeHtml(team.name)}</h3><dl><dt>Players</dt><dd>${team.slots_used} / ${team.roster_slots}</dd><dt>Spent</dt><dd>${money(team.spent)}</dd><dt>Remaining</dt><dd>${money(team.remaining)}</dd><dt>Maximum bid</dt><dd>${money(team.maximum_bid)}</dd></dl></article>`).join('')}
function sortAuction(key){auctionDirection=auctionSort===key&&auctionDirection==='asc'?'desc':'asc';auctionSort=key;renderRankings()}
function renderRankings(){const value=id=>document.querySelector(id)?.value||'';const search=value('#player-search').toLowerCase(),position=value('#position-filter'),columnName=value('#auction-name-filter').toLowerCase(),columnPosition=value('#auction-position-filter'),maxRank=Number(value('#auction-rank-filter'))||null,tier=Number(value('#auction-tier-filter'))||null,selectedId=value('#sale-player-id');const filtered=rankings.filter(row=>(!search||row.player_name.toLowerCase().includes(search))&&(!position||row.position===position)&&(!columnName||row.player_name.toLowerCase().includes(columnName))&&(!columnPosition||row.position===columnPosition)&&(!maxRank||Number(row.overall_rank)<=maxRank)&&(!tier||Number(row.tier)===tier));filtered.sort((a,b)=>{const av=a[auctionSort]??'',bv=b[auctionSort]??'';const compared=auctionSort==='player_name'||auctionSort==='position'?String(av).localeCompare(String(bv)):Number(av||Number.MAX_SAFE_INTEGER)-Number(bv||Number.MAX_SAFE_INTEGER);return auctionDirection==='asc'?compared:-compared});document.querySelector('#ranking-body').innerHTML=filtered.slice(0,300).map(row=>`<tr class="auction-player-row ${row.player_id===selectedId?'selected':''}" data-player-id="${escapeHtml(row.player_id)}" role="button" tabindex="0" aria-selected="${row.player_id===selectedId}" onclick="chooseAuctionRow(event,this)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}"><td>${row.overall_rank}</td><td onclick="event.stopPropagation()">${tierEditor(row)}</td><td><a class="player-name-link" href="${profileHref(row)}" onclick="event.stopPropagation()"><strong>${escapeHtml(row.player_name)}</strong></a><br><small>${escapeHtml(row.nfl_team||'FA')}</small> ${playerFlags(row)}</td><td>${escapeHtml(row.position)}</td><td>${row.projected_points==null?'—':Number(row.projected_points).toFixed(2)}</td><td><strong>${money(row.suggested_auction_value)}</strong></td><td class="dynamic-bid-cell"><strong>${money(row.dynamic_bid)}</strong></td><td><strong>${money(row.max_recommended_bid)}</strong></td></tr>`).join('')||'<tr><td colspan="8">No draftable players match.</td></tr>'}
function renderFranchises(){const select=document.querySelector('#sale-franchise'),selected=select.value;select.innerHTML='<option value="">Select a franchise</option>'+auctionState.franchises.map(team=>`<option value="${escapeHtml(team.franchise_id)}">${escapeHtml(team.name)} · max ${money(team.maximum_bid)}</option>`).join('');if(auctionState.franchises.some(team=>team.franchise_id===selected))select.value=selected;document.querySelector('#auction-franchise-options').innerHTML=auctionState.franchises.map(team=>`<option value="${escapeHtml(team.name)}"></option>`).join('')}
function renderPlayerMatcher(){document.querySelector('#auction-player-options').innerHTML=rankings.map(row=>`<option value="${escapeHtml(row.player_name)}">${escapeHtml(row.position)} · ${escapeHtml(row.nfl_team||'FA')}</option>`).join('')}
function clearAuctionPlayerSelection(){document.querySelector('#sale-player-id').value='';document.querySelector('#sale-amount').value='';document.querySelector('#sale-player-match').textContent='Choose a player from the table or type a matching name.';document.querySelectorAll('.auction-player-row.selected').forEach(row=>{row.classList.remove('selected');row.setAttribute('aria-selected','false')})}
function matchSalePlayer(allowUnique){const input=document.querySelector('#sale-player-name'),needle=input.value.trim().toLowerCase();const exact=rankings.find(row=>row.player_name.toLowerCase()===needle),partial=rankings.filter(row=>row.player_name.toLowerCase().includes(needle));const match=exact||(allowUnique&&partial.length===1?partial[0]:null);if(match)return choosePlayer(match.player_id,match.player_name,match.dynamic_bid??match.suggested_auction_value,false);clearAuctionPlayerSelection();document.querySelector('#sale-player-match').textContent=needle?(partial.length?'Keep typing or choose a suggestion.':'No available player matches that name.'):'Choose a player from the table or type a matching name.'}
function choosePlayer(id,name,value,focusNext=true){document.querySelector('#sale-player-id').value=id;document.querySelector('#sale-player-name').value=name;document.querySelector('#sale-amount').value=value||'';document.querySelector('#sale-player-match').textContent=`Selected: ${name}`;document.querySelectorAll('.auction-player-row').forEach(row=>{const selected=row.dataset.playerId===id;row.classList.toggle('selected',selected);row.setAttribute('aria-selected',String(selected))});if(focusNext)document.querySelector('#sale-franchise-name').focus()}
function chooseAuctionRow(event,rowElement){if(event.target.closest('button,input,select,a'))return;const row=rankings.find(item=>item.player_id===rowElement.dataset.playerId);if(row)choosePlayer(row.player_id,row.player_name,row.dynamic_bid??row.suggested_auction_value)}
function matchSaleFranchise(allowUnique=true){const input=document.querySelector('#sale-franchise-name'),select=document.querySelector('#sale-franchise'),needle=input.value.trim().toLowerCase();const exact=auctionState.franchises.find(team=>team.name.toLowerCase()===needle),partial=auctionState.franchises.filter(team=>team.name.toLowerCase().includes(needle));const match=exact||(allowUnique&&partial.length===1?partial[0]:null);select.value=match?.franchise_id||'';const note=document.querySelector('#sale-franchise-match');note.textContent=match?`Selected: ${match.name}`:needle?(partial.length?'Keep typing or choose a suggestion.':'No franchise matches that name.'):'Type a team name or use the list below.';return match}
function syncSaleFranchiseName(){const team=auctionState.franchises.find(item=>item.franchise_id===document.querySelector('#sale-franchise').value);document.querySelector('#sale-franchise-name').value=team?.name||'';document.querySelector('#sale-franchise-match').textContent=team?`Selected: ${team.name}`:'Type a team name or use the list below.'}
function announceAuctionChange(){localStorage.setItem('draftdesk:auction-change',String(Date.now()))}
async function saveSale(event){event.preventDefault();if(document.querySelector('#sale-franchise-name').value.trim())matchSaleFranchise(true);const payload={league_id:AUCTION_LEAGUE_ID,player_id:document.querySelector('#sale-player-id').value,franchise_id:document.querySelector('#sale-franchise').value,amount:document.querySelector('#sale-amount').value,status:'ROSTER'};if(!payload.player_id)return toast('Choose a player first',true);if(!payload.franchise_id)return toast('Choose a franchise or type one matching team name',true);try{await api('/api/auction/purchases',{method:'POST',body:JSON.stringify(payload)});toast(`${document.querySelector('#sale-player-name').value} sold for ${money(payload.amount)}`);event.target.reset();announceAuctionChange();await refreshAuction()}catch(error){toast(error.message,true)}}
async function undoAuction(){try{await api(`/api/auction/undo?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`,{method:'POST'});toast('Last action undone');announceAuctionChange();await refreshAuction()}catch(error){toast(error.message,true)}}
async function redoAuction(){try{await api(`/api/auction/redo?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`,{method:'POST'});toast('Action restored');announceAuctionChange();await refreshAuction()}catch(error){toast(error.message,true)}}

async function initKeepers(){const search=document.querySelector('#keeper-search');search?.addEventListener('input',()=>loadKeeperRankings(search.value));await Promise.all([loadKeepers(),loadKeeperRankings('')])}
async function loadKeepers(){try{const rows=await api(`/api/leagues/${encodeURIComponent(KEEPER_LEAGUE_ID)}/keepers`);document.querySelector('#keeper-list').innerHTML=rows.map(row=>`<div class="keeper-row"><span><strong>${escapeHtml(row.player_name)}</strong><br><small>Franchise ${escapeHtml(row.franchise_id)} · ${escapeHtml(row.source)}</small></span><span>${money(row.keeper_cost)}</span></div>`).join('')||'<p>No keepers selected.</p>'}catch(error){toast(error.message,true)}}
async function loadKeeperRankings(search){try{const rows=await api(`/api/leagues/${encodeURIComponent(KEEPER_LEAGUE_ID)}/rankings?search=${encodeURIComponent(search)}`);document.querySelector('#keeper-rankings').innerHTML=rows.slice(0,80).map(row=>`<div class="keeper-row"><span><strong>${row.overall_rank}. ${escapeHtml(row.player_name)}</strong><br><small>${escapeHtml(row.position)} · tier ${row.tier}</small></span><span>${row.custom_score}</span></div>`).join('')}catch(error){toast(error.message,true)}}

let catalogPage=1;let catalogRows=[];
function filtersToParams(form){const params=new URLSearchParams(new FormData(form));for(const [key,value] of [...params])if(!value)params.delete(key);params.set('league_id',SELECTED_LEAGUE_ID);params.set('page',catalogPage);return params}
async function initPlayers(){if(!SELECTED_LEAGUE_ID)return toast('Synchronize and select a league first',true);const form=document.querySelector('#player-filters');const saved=new URLSearchParams(location.search);for(const [key,value] of saved){const field=form.elements.namedItem(key);if(field&&key!=='league_id')field.value=value}try{const choices=await api(`/api/players/filters?league_id=${encodeURIComponent(SELECTED_LEAGUE_ID)}`);fillSelect('#catalog-position',choices.positions);fillSelect('#catalog-team',choices.nfl_teams);fillSelect('.column-filters [data-filter=position]',choices.positions);fillSelect('.column-filters [data-filter=nfl_team]',choices.nfl_teams);document.querySelector('#catalog-owner').insertAdjacentHTML('beforeend',choices.franchises.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)}</option>`).join(''));await loadPlayers()}catch(error){toast(error.message,true)}let timer;form.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{catalogPage=1;loadPlayers()},180)});form.addEventListener('reset',()=>setTimeout(()=>{catalogPage=1;loadPlayers()},0));document.querySelectorAll('.column-filters [data-filter]').forEach(field=>field.addEventListener('input',()=>{const target=form.elements.namedItem(field.dataset.filter);if(target)target.value=field.value;clearTimeout(timer);timer=setTimeout(()=>{catalogPage=1;loadPlayers()},180)}))}
function fillSelect(selector,items){document.querySelector(selector).insertAdjacentHTML('beforeend',items.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join(''))}
function sortCatalog(key){const form=document.querySelector('#player-filters');const sort=form.elements.sort;const direction=form.elements.direction;direction.value=sort.value===key&&direction.value==='asc'?'desc':'asc';sort.value=key;catalogPage=1;loadPlayers()}
async function loadPlayers(){const form=document.querySelector('#player-filters');const params=filtersToParams(form);history.replaceState({},'',`${location.pathname}?${params}`);const data=await api(`/api/players?${params}`);catalogRows=data.items;document.querySelector('#player-count').textContent=`${data.pagination.total.toLocaleString()} players`;document.querySelector('#player-freshness').textContent=data.freshness.latest?`Board updated ${shortDate(data.freshness.latest)}`:'No ranking snapshot yet';document.querySelector('#player-body').innerHTML=data.items.map(playerRow).join('')||'<tr><td colspan="10">No players match these filters.</td></tr>';renderPager(data.pagination);renderFilterChips(form)}
function playerRow(row){const pref=row.preference;return `<tr><td>${row.consensus_rank}${row.league_adjusted_rank?`<small class="subrank">Weekly ${row.league_adjusted_rank}</small>`:''}</td><td><a class="player-name-link" href="${profileHref(row)}"><strong>${escapeHtml(row.player_name)}</strong></a> ${playerFlags(row)}</td><td>${escapeHtml(row.position)}</td><td>${escapeHtml(row.nfl_team||'FA')}</td><td>${tierEditor(row)}</td><td>${row.source_count}${row.high_disagreement?' ⚠':''}</td><td>${row.adp??'—'}</td><td>${row.live_auction_value?money(row.live_auction_value):(row.value_over_replacement??'—')}</td><td><span class="status ${row.available?'good':'owned'}">${row.available?'Available':escapeHtml(row.rostered_by||'Drafted')}</span></td><td class="quick-actions"><button class="${pref.target?'active':''}" title="Target" onclick="togglePreference('${row.player_id}','target',${!pref.target})">◎</button><button class="${pref.queue_order?'active':''}" title="Queue" onclick="togglePreference('${row.player_id}','queue_order',${pref.queue_order?'null':row.consensus_rank})">＋</button><button class="${pref.fade?'active':''}" title="Fade" onclick="togglePreference('${row.player_id}','fade',${!pref.fade})">↓</button></td></tr>`}
function renderPager(page){document.querySelector('#player-pages').innerHTML=`<button ${page.page<=1?'disabled':''} onclick="catalogPage--;loadPlayers()">Previous</button><span>Page ${page.page} of ${page.pages}</span><button ${page.page>=page.pages?'disabled':''} onclick="catalogPage++;loadPlayers()">Next</button>`}
function renderFilterChips(form){const labels=[];for(const [key,value] of new FormData(form))if(value&&!['sort','direction'].includes(key)&&!(key==='availability'&&value==='all'))labels.push(`<span>${escapeHtml(key.replace('_',' '))}: ${escapeHtml(value)}</span>`);document.querySelector('#active-filters').innerHTML=labels.join('')}
function activeLeagueId(){return window.SELECTED_LEAGUE_ID||window.AUCTION_LEAGUE_ID||window.KEEPER_LEAGUE_ID||''}
function preferenceRow(playerId){return [...rankings,...catalogRows,...cheatRows,...draftPlayers].find(row=>row.player_id===playerId)}
function preferencePayload(row){const payload={manual_rank:null,manual_tier:null,queue_order:null,target:false,fade:false,do_not_draft:false,notes:null,tags:[],...(row?.preference||{})};delete payload.tags_json;payload.tags=payload.tags||[];return payload}
function tierEditor(row){const manual=row.preference?.manual_tier!=null;return `<input class="tier-input ${manual?'manual':''}" type="number" min="1" max="99" value="${row.tier??''}" aria-label="Tier for ${escapeHtml(row.player_name)}" title="${manual?'Custom tier. Clear to restore calculated tier.':'Change player tier'}" onclick="event.stopPropagation()" onchange="saveTier('${escapeHtml(row.player_id)}',this.value)">`}
async function refreshCurrentBoard(){if(document.querySelector('#ranking-body'))return refreshAuction();if(document.querySelector('#player-body'))return loadPlayers();if(document.querySelector('#cheat-body'))return loadCheat();if(document.querySelector('#draft-player-body'))return loadDraft()}
async function saveTier(playerId,value){const row=preferenceRow(playerId),payload=preferencePayload(row);payload.manual_tier=value===''?null:Number(value);try{await api(`/api/leagues/${encodeURIComponent(activeLeagueId())}/preferences/${encodeURIComponent(playerId)}`,{method:'PATCH',body:JSON.stringify(payload)});toast(payload.manual_tier?`Tier changed to ${payload.manual_tier}`:'Calculated tier restored');await refreshCurrentBoard()}catch(error){toast(error.message,true)}}
async function togglePreference(playerId,key,value){const payload=preferencePayload(preferenceRow(playerId));payload[key]=value;try{await api(`/api/leagues/${encodeURIComponent(activeLeagueId())}/preferences/${encodeURIComponent(playerId)}`,{method:'PATCH',body:JSON.stringify(payload)});toast('Preference saved');await refreshCurrentBoard()}catch(error){toast(error.message,true)}}
async function showPlayer(playerId){location.href=`/player/${encodeURIComponent(playerId)}?league_id=${encodeURIComponent(activeLeagueId())}`}

function sourceLabel(id){return ({league_model:'Weekly league model',mfl_rank:'MFL player rank',mfl_adp:'MFL ADP',fantasypros:'FantasyPros ECR',gng:'The GNG',user_csv:'Imported ranking'})[id]||id.replaceAll('_',' ')}
async function initPlayerProfile(){try{const row=await api(`/api/players/${encodeURIComponent(PROFILE_PLAYER_ID)}?league_id=${encodeURIComponent(SELECTED_LEAGUE_ID)}`);const profile=row.profile||{},metadata=row.metadata||{},nflverse=metadata.nflverse||{},sleeper=metadata.sleeper||{},fp=profile.fantasypros||{},gng=profile.gng||{};const flags=(profile.flags||[]).map(flag=>`<span class="player-flag">${escapeHtml(flag)}</span>`).join('');const photo=profile.headshot_url?`<img src="${escapeHtml(profile.headshot_url)}" alt="${escapeHtml(row.player_name)} headshot">`:`<div class="profile-initials">${escapeHtml(row.position)}</div>`;document.querySelector('#profile-hero').innerHTML=`${photo}<div><p class="eyebrow">${escapeHtml(row.nfl_team||'Free agent')} · ${escapeHtml(row.position)}${row.consensus_position_rank?` · consensus ${escapeHtml(row.position)}${row.consensus_position_rank}`:''}</p><h1>${escapeHtml(row.player_name)}</h1><div class="profile-flags">${flags||'<span class="player-flag">No active flags</span>'}</div><p>Consensus rank <strong>#${row.consensus_rank??'—'}</strong> · Tier <strong>${row.tier??'—'}</strong> · ${escapeHtml(row.source_confidence||'no')} source confidence</p></div><div class="profile-links">${(profile.external_links||[]).map(link=>`<a class="button" href="${escapeHtml(link.url)}" target="_blank" rel="noreferrer">${escapeHtml(link.label)}${link.guessed?' ↗*':' ↗'}</a>`).join('')}</div>`;document.querySelector('#overview').innerHTML=`<article class="panel"><h2>Overview</h2><dl class="profile-facts"><dt>Availability</dt><dd>${row.available?'Available':escapeHtml(row.rostered_by||'Drafted')}</dd><dt>Rookie</dt><dd>${row.rookie?'Yes':'No'}</dd><dt>Injury</dt><dd>${escapeHtml(row.injury_status||'None reported')}</dd><dt>College</dt><dd>${escapeHtml(nflverse.college||'—')}</dd><dt>Experience</dt><dd>${escapeHtml(nflverse.years_of_experience??sleeper.years_exp??'—')} years</dd><dt>Jersey</dt><dd>${escapeHtml(sleeper.number??'—')}</dd></dl></article><article class="panel"><h2>Draft read</h2><div class="metric-grid"><div><span>Consensus rank</span><strong>${row.consensus_rank??'—'}</strong></div><div><span>Weekly model rank</span><strong>${row.league_adjusted_rank??'—'}</strong></div><div><span>Tier</span><strong>${row.tier??'—'}</strong></div><div><span>ADP</span><strong>${row.adp??'—'}</strong></div></div><p class="muted">Tier source: ${escapeHtml(row.tier_source||'consensus')}. Weekly model rank uses MFL’s current weekly projection and is separate from the multi-source consensus.</p></article>`;document.querySelector('#profile-rankings').innerHTML=`<div class="profile-ranking-grid"><article><span>Best source rank</span><strong>${row.best_rank??'—'}</strong></article><article><span>Median source rank</span><strong>${row.median_rank??'—'}</strong></article><article><span>Worst source rank</span><strong>${row.worst_rank??'—'}</strong></article><article><span>Independent source families</span><strong>${row.source_family_count??0}</strong></article></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Rank signal</th></tr></thead><tbody>${Object.entries(row.source_ranks||{}).map(([source,rank])=>`<tr><td>${escapeHtml(sourceLabel(source))}</td><td>${escapeHtml(rank)}</td></tr>`).join('')||'<tr><td colspan="2">No rank signals yet.</td></tr>'}</tbody></table></div>`;document.querySelector('#profile-auction').innerHTML=`<div class="auction-profile-values"><article><span>Suggested bid</span><strong>${money(row.suggested_auction_value)}</strong><p>Model target at the league’s current remaining budgets.</p></article><article><span>Maximum recommended bid</span><strong>${money(row.max_recommended_bid)}</strong><p>Upper target before the value becomes too aggressive.</p></article><article><span>League legal ceiling</span><strong>${money(row.league_maximum_bid)}</strong><p>Highest legal bid currently available to any franchise.</p></article></div>`;const fpHtml=Object.keys(fp).length?`<article class="source-analysis-card"><span class="pill">FantasyPros</span><h3>ECR ${escapeHtml(fp.rank_ecr??'—')} · ${escapeHtml(fp.pos_rank??row.position)}</h3><p>Expert range ${escapeHtml(fp.rank_min??'—')}–${escapeHtml(fp.rank_max??'—')} · FantasyPros tier ${escapeHtml(fp.tier??'—')} · ${escapeHtml(fp.scoring||'league')} scoring.</p></article>`:'<article class="source-analysis-card"><span class="pill">FantasyPros</span><h3>No API row matched</h3><p>The generated external profile link may still work.</p></article>';const gngHtml=Object.keys(gng).length?`<article class="source-analysis-card"><span class="pill">The GNG</span><h3>Overall ${escapeHtml(gng.rank??'—')} · position ${escapeHtml(gng.position_rank??'—')}</h3><p>${escapeHtml(gng.verdict||'No written verdict supplied.')}</p>${gng.projected_ppg!=null?`<strong>${escapeHtml(gng.projected_ppg)} projected points per game</strong>`:''}</article>`:'<article class="source-analysis-card"><span class="pill">The GNG</span><h3>No current row matched</h3></article>';document.querySelector('#profile-sources').innerHTML=`<div class="profile-source-grid">${fpHtml}${gngHtml}<article class="source-analysis-card"><span class="pill">Identity</span><h3>Cross-source match</h3><dl class="profile-facts"><dt>MFL</dt><dd>${escapeHtml(row.identity.mfl_id||'—')}</dd><dt>GSIS</dt><dd>${escapeHtml(row.identity.gsis_id||'—')}</dd><dt>ESPN</dt><dd>${escapeHtml(row.identity.espn_id||'—')}</dd><dt>Confidence</dt><dd>${escapeHtml(row.identity.match_confidence||'—')}</dd></dl></article></div>${(profile.external_links||[]).some(link=>link.guessed)?'<p class="muted">* The FantasyPros URL was generated from the player name because the API did not provide a direct profile link. It may not resolve.</p>':''}`;initResizableTables()}catch(error){toast(error.message,true);document.querySelector('#profile-hero').innerHTML=`<div class="notice warning">${escapeHtml(error.message)}</div>`}}

