    document.querySelector('#profile-auction').innerHTML=`<div class="auction-profile-values"><article><span>Suggested bid</span><strong>${money(row.suggested_auction_value)}</strong><p>Stable pre-auction baseline.</p></article><article class="dynamic-value"><span>Dynamic bid</span><strong>${money(row.dynamic_bid)}</strong><p>Live value from remaining money and players.</p></article><article><span>Maximum recommended bid</span><strong>${money(row.max_recommended_bid)}</strong><p>Current recommended ceiling.</p></article><article><span>League legal ceiling</span><strong>${money(row.league_maximum_bid)}</strong><p>Highest legal bid any franchise can make.</p></article></div>`
    const fpHtml=Object.keys(fp).length?`<article class="source-analysis-card"><span class="pill">FantasyPros</span><h3>ECR ${escapeHtml(fp.rank_ecr??'—')} · ${escapeHtml(fp.pos_rank??row.position)}</h3><p>Expert range ${escapeHtml(fp.rank_min??'—')}–${escapeHtml(fp.rank_max??'—')} · FantasyPros tier ${escapeHtml(fp.tier??'—')} · ${escapeHtml(fp.scoring||'league')} scoring.</p></article>`:`<article class="source-analysis-card"><span class="pill">FantasyPros</span><h3>${row.position==='DEF'?'Team-defense news profile':'No API row matched'}</h3><p>${row.position==='DEF'?'Use the FantasyPros defense link above for team-specific analysis.':'The generated external profile link may still work.'}</p></article>`
    const gngHtml=Object.keys(gng).length?`<article class="source-analysis-card"><span class="pill">The GNG</span><h3>Overall ${escapeHtml(gng.rank??'—')} · position ${escapeHtml(gng.position_rank??'—')}</h3><p>${escapeHtml(gng.verdict||'No written verdict supplied.')}</p>${gng.projected_ppg!=null?`<strong>${escapeHtml(gng.projected_ppg)} projected points per game</strong>`:''}</article>`:'<article class="source-analysis-card"><span class="pill">The GNG</span><h3>No current row matched</h3></article>'
    document.querySelector('#profile-sources').innerHTML=`<div class="profile-source-grid">${fpHtml}${gngHtml}<article class="source-analysis-card"><span class="pill">Identity</span><h3>Cross-source match</h3><dl class="profile-facts"><dt>MFL</dt><dd>${escapeHtml(row.identity.mfl_id||'—')}</dd><dt>GSIS</dt><dd>${escapeHtml(row.identity.gsis_id||'—')}</dd><dt>ESPN</dt><dd>${escapeHtml(row.identity.espn_id||'—')}</dd><dt>Confidence</dt><dd>${escapeHtml(row.identity.match_confidence||'—')}</dd></dl></article></div>${(profile.external_links||[]).some(link=>link.guessed)?'<p class="muted">* The FantasyPros URL was generated from the player name because the API did not provide a direct profile link. It may not resolve.</p>':''}`
    const stats=nerdy.stats&&typeof nerdy.stats==='object'?nerdy.stats:{}
    document.querySelector('#profile-nerdy-stats').innerHTML=Object.keys(stats).length?`<p><strong>${escapeHtml(nerdy.season||'—')} ${escapeHtml(nerdy.summary_level||'regular season')}</strong> · ${escapeHtml(nerdy.team||row.nfl_team||'—')} · nflverse (CC-BY-4.0)</p><div class="table-wrap"><table><thead><tr><th>Statistic</th><th>Value</th></tr></thead><tbody>${Object.entries(stats).map(([key,value])=>`<tr><td>${escapeHtml(key.replaceAll('_',' '))}</td><td>${escapeHtml(value)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">No nflverse historical-stat snapshot is matched to this player yet. Refresh nflverse under Sources.</div>'
